SELECT CAST(COUNT(DISTINCT CASE WHEN p.drug_type = 'insulin' THEN e.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.subject_id), 0) AS insulin_prevalence_first_24h, CAST(COUNT(DISTINCT CASE WHEN p.drug_type = 'oral' THEN e.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.subject_id), 0) AS oral_prevalence_first_24h, (CAST(COUNT(DISTINCT CASE WHEN p.drug_type = 'insulin' THEN e.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.subject_id), 0) - CAST(COUNT(DISTINCT CASE WHEN p.drug_type = 'oral' THEN e.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.subject_id), 0)) * 100 AS net_change FROM emar e JOIN patients p ON e.subject_id = p.subject_id JOIN admissions a ON e.hadm_id = a.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 68 AND a.admittime BETWEEN 63 AND 73 AND a.dischtime BETWEEN 63 AND 73 AND p.dod IS NULL AND (a.admission_type = 'ACUTE' OR a.admission_type = 'CHRONIC') AND (e.event_txt = 'POE' OR e.event_txt = 'POE-DRG') AND (e.starttime <= 24 AND e.endtime >= 24) GROUP BY e.subject_id;